import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type ChocolateTransformationProps = Record<string, any>;

const Suffix: React.FC<{
  text: string;
  start: number;
  exit: number;
  fps: number;
  frame: number;
  textColor: string;
  fontSize: number;
}> = ({ text, start, exit, fps, frame, textColor, fontSize }) => {
  const enterSpring = spring({
    frame: frame - start,
    fps,
    config: { damping: 14, mass: 0.8 },
  });
  
  const exitSpring = spring({
    frame: frame - exit,
    fps,
    config: { damping: 14, mass: 0.8 },
  });

  const opacityIn = interpolate(enterSpring, [0, 1], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const opacityOut = interpolate(exitSpring, [0, 1], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const opacity = opacityIn - opacityOut;

  // Slide out from the left (hidden behind the base letter) and exit by falling down
  const translateX = interpolate(enterSpring, [0, 1], [-fontSize * 0.8, 0], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const translateY = interpolate(exitSpring, [0, 1], [0, fontSize * 0.4], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const rotateX = interpolate(exitSpring, [0, 1], [0, 60], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });

  return (
    <div
      style={{
        position: "absolute",
        left: 0,
        bottom: 0,
        fontSize: `${fontSize}px`,
        fontWeight: 700,
        color: textColor,
        opacity,
        transform: `translate(${translateX}px, ${translateY}px) rotateX(${rotateX}deg)`,
        transformOrigin: "bottom center",
        lineHeight: 1,
        whiteSpace: "pre",
        transition: "none",
      }}
    >
      {text}
    </div>
  );
};

const ChocolateTransformation: React.FC<ChocolateTransformationProps> = ({
  backgroundColor = "#FDF8F5",
  transparentBackground = false,
  durationInSeconds = 8,
  primaryColor = "#3E1C00",
  secondaryColor = "#5A2E00",
  baseLetter = "C",
  suffixes = ["ontext", "larity", "ues"],
}) => {
  {/* Load TT Chocolates font as requested */}
  useFontLoader(["TT Chocolates"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timing logic
  const totalFrames = durationInSeconds * fps;
  const introDuration = 40; 
  const wordsDuration = totalFrames - introDuration;
  const slot = wordsDuration / Math.max(1, suffixes.length);

  // Intro Springs
  const cEnter = spring({
    frame,
    fps,
    config: { damping: 12, mass: 0.8 },
  });

  // Responsive Scaling
  const fontSize = width * 0.12;

  // Render invisible longest word to maintain baseline and flex alignment without hardcoded heights
  const longestWord = useMemo(() => {
    return [...suffixes].sort((a, b) => b.length - a.length)[0] || "";
  }, [suffixes]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: '"TT Chocolates", sans-serif', transition: "none" }}>
      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          transform: `translate(-50%, -50%)`,
          display: "flex",
          flexDirection: "row",
          alignItems: "baseline",
          transition: "none",
        }}
      >
        {/* The Anchor Letter */}
        <div
          style={{
            fontSize: `${fontSize}px`,
            fontWeight: 900, // Black weight for a thick, rich chocolate look
            color: primaryColor,
            transform: `scale(${interpolate(cEnter, [0, 1], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" })})`,
            opacity: interpolate(cEnter, [0, 1], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" }),
            zIndex: 10,
            lineHeight: 1,
            transition: "none",
          }}
        >
          {baseLetter}
        </div>

        {/* The Transforming Suffixes */}
        <div
          style={{
            position: "relative",
            marginLeft: -fontSize * 0.04, // Slight tuck to fix standard font kerning gap
            zIndex: 1,
            clipPath: "inset(-100% -100% -100% 0)", // Only clips the left edge allowing elements to slide *out* from the C
            transition: "none",
          }}
        >
          {/* Invisible spacer dictates layout height/baseline */}
          <span
            style={{
              opacity: 0,
              fontSize: `${fontSize}px`,
              fontWeight: 700,
              pointerEvents: "none",
              lineHeight: 1,
              transition: "none",
            }}
          >
            {longestWord}
          </span>

          {suffixes.map((word, i) => {
            const start = introDuration + i * slot;
            const isLast = i === suffixes.length - 1;
            // The last word stays on screen until the very end
            const exit = isLast ? totalFrames + 100 : start + slot - 15;

            return (
              <Suffix
                key={`suffix-${i}`}
                text={word}
                start={start}
                exit={exit}
                fps={fps}
                frame={frame}
                textColor={secondaryColor}
                fontSize={fontSize}
              />
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ChocolateTransformation;